UPDATE sq_auth_rate_bucket
SET failures = 0,
    locked_until = NULL,
    window_start = #{now}
WHERE bucket_key = #{bucketKey}

UPDATE sq_auth_session
SET revoked_at = #{now}
WHERE session_id = #{sessionId} AND revoked_at IS NULL

UPDATE sq_auth_session
SET revoked_at = #{now}
WHERE user_id = #{userId} AND revoked_at IS NULL
